<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {usePhaseThreeText} from '../phaseThreeText'
import {dateRangeValid,leaveActions} from '../timekeepingUi'
import {addDays,storeToday} from '../time'
import type {Leave,LeaveDecision} from '../phaseThreeTypes'
import type {AttendanceDetail} from '../types'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),id=String(route.params.id),{api,home,t,p,base,loading,busy,failure,notice,load,write,format}=usePhasePage(),{q}=usePhaseThreeText(),from=typeof route.query.from==='string'?route.query.from:addDays(storeToday(),-30),to=typeof route.query.to==='string'?route.query.to:storeToday(),item=ref<Leave|null>(null),zone=ref('Asia/Singapore'),note=ref('')
const actions=computed(()=>item.value?leaveActions(item.value,home.value):[])
const needsNote=computed(()=>actions.value.some(s=>['approved','rejected','cancel_requested','cancelled','cancel_rejected'].includes(s)))
function refresh(){if(!dateRangeValid(from,to)){failure.value=p('invalid');return}item.value=null;void load(async()=>{const leaves=await api().get<Leave[]>(`/leaves?from=${from}&to=${to}`),selected=leaves.find(l=>l.id===id);if(!selected)return {selected:null,zone:''};const a=await api().get<AttendanceDetail>('/attendance/'+selected.scheduleId);return {selected,zone:a.attendance.schedule.timezone}},v=>{item.value=v.selected;if(!v.selected){failure.value=t('notFound');return}zone.value=v.zone})}
function label(s:LeaveDecision){return s==='approved'?p('approve'):s==='rejected'?p('reject'):s==='withdrawn'?p('withdraw'):s==='cancel_requested'?q('requestCancellation'):s==='cancelled'?q('approveCancellation'):q('rejectCancellation')}
function decide(status:LeaveDecision){if(!item.value||!actions.value.includes(status))return;if(needsNote.value&&!note.value.trim()){failure.value=p('invalid');return}void write(()=>api().put('/leaves/'+id+'/decision',{expectedVersion:item.value!.version,status,note:note.value.trim()}),refresh)}
onMounted(refresh)
</script>
<template><section class="wf-panel wf-form-panel"><header class="wf-toolbar"><h2>{{q('leaveDetails')}}</h2><button :disabled="loading||busy" @click="refresh">{{t('refresh')}}</button></header><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><template v-if="item&&!loading"><dl class="wf-details"><dt>{{p('employee')}}</dt><dd>{{item.employeeName}}</dd><dt>{{p('status')}}</dt><dd><span class="wf-badge">{{q(item.status)}}</span></dd><dt>{{q('leaveTypes')}}</dt><dd>{{item.typeName}} · {{q(item.paid?'paid':'unpaid')}}</dd><dt>{{q('leaveStart')}}</dt><dd>{{format(item.startAt,zone)}}</dd><dt>{{q('leaveEnd')}}</dt><dd>{{format(item.endAt,zone)}}</dd><dt>{{p('timezone')}}</dt><dd>{{zone}}</dd><dt>{{p('reason')}}</dt><dd class="wf-preserve">{{item.reason}}</dd><dt>{{p('created')}}</dt><dd>{{format(item.createdAt,zone)}}</dd><dt v-if="item.reviewNote">{{p('note')}}</dt><dd v-if="item.reviewNote" class="wf-preserve">{{item.reviewNote}}</dd><dt v-if="item.reviewerId">{{p('reviewer')}}</dt><dd v-if="item.reviewerId">{{item.reviewerId}}</dd></dl><p class="wf-hint">{{q('cancelHint')}}</p><RouterLink :to="base+'/attendance/'+item.scheduleId">{{q('rawDetails')}}</RouterLink><form v-if="actions.length" class="wf-section" @submit.prevent="decide(actions[0]!)"><label v-if="needsNote">{{actions.includes('cancel_requested')?p('reason'):p('note')}}<textarea v-model="note" required rows="3" maxlength="500" :disabled="busy"></textarea></label><footer class="wf-form-actions"><button v-for="(action,index) in actions" :key="action" type="button" :class="{primary:index===0}" :disabled="busy||(needsNote&&!note.trim())" @click="decide(action)">{{busy?t('saving'):label(action)}}</button></footer></form><p v-else-if="home?.myself?.id===item.employeeId&&home?.employeeManage" class="wf-hint">{{p('selfReview')}}</p></template></section></template>
